{
  "title": "Is the new checkout message better?",
  "setting": "Day 2 at Lumen Cart",
  "mission": "You’re a junior marketing analyst reviewing a checkout experiment. Recommend **whether to launch the new message** and explain what the evidence supports.",
  "deadline": "Launch meeting with {{product}} today at 3:00 p.m.",
  "panels": [
    {
      "title": "Checkout experiment",
      "metrics": [
        {
          "label": "A: current message",
          "value": "3.0% purchased",
          "note": "30 purchases from 1,000 visitors"
        },
        {
          "label": "B: new message",
          "value": "3.6% purchased",
          "note": "36 purchases from 1,000 visitors"
        },
        {
          "label": "Planned sample",
          "value": "10,000 visitors per version",
          "note": "Set before the experiment began"
        },
        {
          "label": "Final evidence threshold",
          "value": "5%",
          "note": "Use once, at the planned sample size"
        }
      ],
      "note": "Visitors are randomly assigned. Each visitor is counted once. Only the checkout message differs."
    }
  ],
  "team": [
    {
      "id": "data",
      "role": "Experimentation analyst",
      "expertise": "Checks experiment design and helps you judge uncertainty.",
      "ai": false
    },
    {
      "id": "product",
      "role": "Product manager",
      "expertise": "Owns the launch schedule and wants more completed purchases.",
      "ai": false
    },
    {
      "id": "ai",
      "role": "AI assistant",
      "expertise": "Runs requested calculations; people check its assumptions and decide.",
      "ai": true
    }
  ],
  "meters": [
    {
      "id": "risk",
      "label": "Risk of an unsupported decision",
      "start": 50,
      "goodWhen": "low"
    },
    {
      "id": "momentum",
      "label": "Launch momentum",
      "start": 75,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "chance",
      "name": "Tell a real difference from chance",
      "practice": "Write two sentences explaining why 36 purchases versus 30 does not, by itself, establish that one message is better."
    },
    {
      "id": "sample",
      "name": "Choose a sample size",
      "practice": "For one experiment, write the smallest improvement worth detecting and two reasons its sample size should be planned in advance."
    },
    {
      "id": "explain",
      "name": "Explain a test result",
      "practice": "Explain one experiment result in three sentences: the observed gap, the uncertainty, and your recommended action."
    }
  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "product",
          "text": "B has six more purchases. Can we put the new message in front of everyone today?"
        },
        {
          "from": "data",
          "text": "Hypothesis testing asks whether a gap like this could appear just by chance if neither version were better. A higher purchase rate alone doesn’t settle that."
        }
      ],
      "prompt": "How do you begin your review?",
      "choices": [
        {
          "id": "use-gap",
          "text": "Use the higher purchase rate to recommend B, and leave the statistical check for later.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I’ll prepare the launch request, but I still need your recommendation before changing traffic."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "momentum",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "The observed lead could reflect chance. Check the evidence before treating the higher rate as a reliable improvement.",
              "example": "\"B is ahead so far; let’s check whether that gap is convincing.\""
            }
          ],
          "next": "unchecked"
        },
        {
          "id": "ask-ai",
          "text": "Ask the AI to check the gap using the visitor counts, then review its assumptions with {{data}}.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "Using a two-sided comparison of purchase rates, the current p-value is about 0.45. If neither version were better, gaps at least this large would occur in about 45% of comparable tests."
            },
            {
              "from": "data",
              "text": "A p-value measures how surprising the result would be under no real difference; it isn’t the chance that B works. Random assignment and one count per visitor support this calculation, but this early check isn’t our planned final test."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -15
            },
            {
              "meter": "momentum",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You requested a relevant calculation and checked its assumptions with a colleague instead of accepting the AI’s output on its own.",
              "example": null
            }
          ],
          "next": "checked"
        }
      ]
    },
    {
      "id": "unchecked",
      "messages": [
        {
          "from": "data",
          "text": "Your launch draft treats B’s lead as established, but no statistical check supports that yet. We also have only one-tenth of the planned visitors."
        },
        {
          "from": "product",
          "text": "We can spare a few minutes for a review. Waiting for the full sample would move the launch out of this week."
        }
      ],
      "prompt": "What do you do with the draft recommendation?",
      "choices": [
        {
          "id": "keep-draft",
          "text": "Keep the early launch recommendation and use the observed lead as the main evidence.",
          "quality": "weak",
          "replies": [
            {
              "from": "data",
              "text": "I’ll flag that the planned test is incomplete. Traffic will stay evenly split until you give the final launch instruction."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "momentum",
              "change": 5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "A promising early result does not replace the planned sample. Keep the stopping rule tied to the evidence needed, not the direction of the latest numbers.",
              "example": "Review the original sample plan before approving an early launch."
            }
          ],
          "next": "limited"
        },
        {
          "id": "check-now",
          "text": "Pause the draft and ask the AI and {{data}} to review the gap and original sample plan.",
          "quality": "strong",
          "replies": [
            {
              "from": "ai",
              "text": "The current two-sided p-value is about 0.45: a gap at least this large would be common if neither message were better. That does not establish that the messages are equal."
            },
            {
              "from": "data",
              "text": "The calculation fits our random assignment and visitor counts. A p-value measures surprise under no real difference; this early review is not the planned final test."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "momentum",
              "change": -5
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "good",
              "text": "You revised the draft when its evidence was questioned and asked for a check before committing traffic.",
              "example": null
            }
          ],
          "next": "checked"
        }
      ]
    },
    {
      "id": "checked",
      "messages": [
        {
          "from": "data",
          "text": "We chose 10,000 visitors per version before starting, using the usual 3% purchase rate and a worthwhile target of about 3.75%. Smaller improvements generally need more visitors to detect reliably."
        },
        {
          "from": "product",
          "text": "At current traffic, reaching that sample takes another week. Waiting costs us this week’s launch slot; launching now means accepting uncertainty."
        }
      ],
      "prompt": "Which plan do you recommend?",
      "choices": [
        {
          "id": "finish-plan",
          "text": "Keep the even split for one more week and make the launch decision at the planned sample.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "I’ll move the launch slot. Give me a clear recommendation when the planned comparison is ready."
            },
            {
              "from": "ai",
              "text": "At the planned sample, A has 300 purchases and B has 360, from 10,000 visitors each. The final two-sided p-value is about 0.018, below the agreed 0.05 threshold."
            },
            {
              "from": "data",
              "text": "That is evidence against no real difference. It does not guarantee that future visitors will produce the same improvement."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -20
            },
            {
              "meter": "momentum",
              "change": -20
            }
          ],
          "timeJump": {
            "label": "One week later",
            "panel": {
              "title": "Planned final comparison",
              "metrics": [
                {
                  "label": "A: current message",
                  "value": "3.0% purchased",
                  "note": "300 purchases from 10,000 visitors"
                },
                {
                  "label": "B: new message",
                  "value": "3.6% purchased",
                  "note": "360 purchases from 10,000 visitors"
                },
                {
                  "label": "Observed gap",
                  "value": "0.6 percentage points",
                  "note": "6 additional purchases per 1,000 visitors"
                },
                {
                  "label": "Final p-value",
                  "value": "About 0.018",
                  "note": "Below the agreed 0.05 threshold"
                }
              ],
              "note": "The planned sample is complete. Assignment and counting checks found no issues."
            }
          },
          "notes": [
            {
              "skill": "sample",
              "kind": "good",
              "text": "You honored a sample plan tied to a worthwhile improvement rather than stopping as soon as one version looked better.",
              "example": null
            },
            {
              "skill": "chance",
              "kind": "good",
              "text": "You used the agreed final comparison to judge the evidence, while accepting the scheduling cost of waiting.",
              "example": null
            }
          ],
          "next": "ready"
        },
        {
          "id": "launch-early",
          "text": "Keep this week’s launch slot and proceed toward B despite the incomplete comparison.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "The slot stays open. I’ll wait for your final wording before moving everyone to B."
            },
            {
              "from": "data",
              "text": "The early check did not support a reliable difference. Any launch now is a business choice under uncertainty, not a demonstrated experiment win."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 20
            },
            {
              "meter": "momentum",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "sample",
              "kind": "improve",
              "text": "You preserved the schedule, but left the planned evidence unfinished. Separate a deadline-driven business choice from a conclusion supported by the experiment.",
              "example": "\"We can launch early, but we cannot call B a demonstrated winner.\""
            }
          ],
          "next": "limited"
        }
      ]
    },
    {
      "id": "ready",
      "messages": [
        {
          "from": "product",
          "text": "The planned comparison is complete. What should I tell the launch team in plain English?"
        },
        {
          "from": "data",
          "text": "The observed increase is 0.6 percentage points, or 20% relative to A’s rate. Keep that observed result separate from any promise about future sales."
        }
      ],
      "prompt": "What recommendation do you send?",
      "choices": [
        {
          "id": "wait-again",
          "text": "Keep both versions running until we can be certain that B will improve future sales.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I’ll hold the wider rollout again. I need a usable decision rule, though; we can’t wait for a guarantee."
            },
            {
              "from": "data",
              "text": "More observations cannot guarantee future performance. The agreed final test already provides evidence for a launch decision."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 5
            },
            {
              "meter": "momentum",
              "change": -15
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "improve",
              "text": "Asking for certainty makes the decision impossible to finish. Explain the strength and limits of the completed evidence, then recommend an action.",
              "example": "\"The planned test supports B, although future gains may differ. I recommend launching and monitoring.\""
            }
          ],
          "next": "held"
        },
        {
          "id": "recommend-b",
          "text": "Recommend B: the planned test supports the observed gain, but future results may differ.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "That gives me an action and a clear limit. I’ll approve the rollout and keep watching the purchase rate."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -10
            },
            {
              "meter": "momentum",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You translated the evidence into a practical recommendation without presenting the observed gain as a guarantee.",
              "example": null
            }
          ],
          "next": "launched"
        }
      ]
    },
    {
      "id": "limited",
      "messages": [
        {
          "from": "product",
          "text": "We’re still at 1,000 visitors per version, and traffic remains evenly split. Your early launch request needs a final instruction."
        },
        {
          "from": "data",
          "text": "The planned comparison is unfinished. Please don’t describe six extra purchases as proof that B is better."
        }
      ],
      "prompt": "What final instruction do you give?",
      "choices": [
        {
          "id": "hold-launch",
          "text": "Hold the wider launch and explain that B’s early lead still needs the planned comparison.",
          "quality": "strong",
          "replies": [
            {
              "from": "product",
              "text": "I’ll leave traffic evenly split and move the launch slot. We’ll return to the decision at the planned sample."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": -15
            },
            {
              "meter": "momentum",
              "change": -20
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "explain",
              "kind": "good",
              "text": "You corrected the launch message and clearly separated an early lead from a supported conclusion.",
              "example": null
            },
            {
              "skill": "sample",
              "kind": "good",
              "text": "You kept the wider rollout on hold so the original comparison can be completed.",
              "example": null
            }
          ],
          "next": "held"
        },
        {
          "id": "declare-win",
          "text": "Approve the wider launch and describe B’s higher purchase rate as an experiment win.",
          "quality": "weak",
          "replies": [
            {
              "from": "product",
              "text": "I’ll launch B today. {{data}} has flagged the claim, so the launch record will show that the planned test was not completed."
            },
            {
              "from": "data",
              "text": "We’ll monitor sales, but that won’t complete this original comparison once everyone receives B."
            }
          ],
          "effects": [
            {
              "meter": "risk",
              "change": 15
            },
            {
              "meter": "momentum",
              "change": 10
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "chance",
              "kind": "improve",
              "text": "You treated an early lead as proof and ended the comparison before its planned sample. The launch may work, but this evidence does not establish that it will.",
              "example": "\"This is an early business launch, not a demonstrated experiment win.\""
            }
          ],
          "next": "early"
        }
      ]
    }
  ],
  "endings": [
    {
      "id": "launched",
      "outcome": "B is approved for wider rollout after the planned test: 3.0% versus 3.6%, an observed increase of 6 purchases per 1,000 visitors. The launch team understands that future gains may differ."
    },
    {
      "id": "held",
      "outcome": "The wider rollout stays on hold and visitors remain evenly split. Your final recommendation delays the launch rather than changing everyone to B."
    },
    {
      "id": "early",
      "outcome": "B launches using the early result of 30 versus 36 purchases from 1,000 visitors per version. The launch record flags the unsupported win claim, and the original experiment ends without its planned comparison."
    }
  ],
  "summary": [
    "A higher observed rate can come from chance; hypothesis testing evaluates evidence against no real difference.",
    "Plan sample size around the improvement worth detecting, and avoid stopping simply because an early result looks favorable.",
    "Explain the observed result, its uncertainty, and the recommended action without promising future performance."
  ]
}

{
  "title": "E se você pudesse ver a luz chegando?",
  "setting": "Uma tarde no Museu Faísca",
  "mission": "Você pode explorar uma sala que registra a chegada da luz numa tela. Prepare uma demonstração para mostrar **como a luz chega em pacotes e também se comporta como onda**.",
  "deadline": null,
  "panels": [
