        {
          "label": "Caminho até a tela",
          "value": "Duas aberturas estreitas",
          "note": "As duas ficam abertas durante a experiência."
        },
        {
          "label": "Tela especial",
          "value": "Registra cada chegada",
          "note": "Cada registro aparece como um pontinho."
