    {
      "id": "tech",
      "role": "Técnico da sala",
      "expertise": "Ajusta a luz e conhece o que a tela consegue registrar.",
      "ai": false
    }
  ],
  "meters": [
    {
      "id": "clues",
      "label": "Pistas reunidas",
      "start": 0,
      "goodWhen": "high"
    }
  ],
  "skills": [
    {
      "id": "packets",
      "name": "Energia em pacotes",
      "practice": "Explique em duas frases o que muda ao diminuir o brilho de uma luz sem mudar sua cor: a quantidade de pacotes, não a energia de cada pacote."
