  ],
  "startNodeId": "start",
  "nodes": [
    {
      "id": "start",
      "messages": [
        {
          "from": "guide",
          "text": "E se a gente pudesse acompanhar a luz chegando, em vez de ver só uma tela iluminada? Quero uma demonstração que os visitantes possam descobrir com você."
