          "timeJump": null,
          "notes": [
            {
              "skill": "duality",
              "kind": "good",
              "text": "Você buscou o desenho coletivo, que dá uma pista do comportamento de onda da luz.",
              "example": null
            },
            {
              "skill": "packets",
              "kind": "improve",
              "text": "Para investigar os pacotes, faça também uma observação com pouca luz, em que as chegadas possam ser distinguidas.",
              "example": "Peça menos brilho e acompanhe os registros individuais."
            }
          ],
          "next": "bright-view"
        },
        {
          "id": "dim",
          "text": "Peço bem pouco brilho para acompanhar as chegadas uma de cada vez.",
          "quality": "strong",
          "replies": [
            {
              "from": "tech",
              "text": "Aparecem pontinhos separados, em lugares diferentes. Cada um registra a chegada de um pacote de luz inteiro, também chamado de fóton; não aparece um pontinho cada vez mais fraco."
