          ],
          "effects": [
            {
              "meter": "clues",
              "change": 35
            }
          ],
          "timeJump": null,
          "notes": [
            {
              "skill": "packets",
              "kind": "good",
              "text": "Você ajustou a experiência para observar as chegadas individuais, em vez de confundir menos brilho com pacotes menores.",
              "example": null
            }
          ],
          "next": "dim-view"
        }
      ]
    },
    {
      "id": "dim-view",
      "messages": [
